        let (result_tx, result_rx) = mpsc::channel();
        let (finish_ui_tx, finish_ui_rx) = mpsc::channel();
        let (complete_tx, complete_rx) = mpsc::channel();
        let ui = thread::spawn(move || {
            result_tx
                .send(app.dispatch(AppCommand::Stop { job_id, generation }))
                .unwrap();
            finish_ui_rx.recv().unwrap();
            event_tx
                .send(ImportEvent::Published { job_id, generation })
                .unwrap();
            complete_tx.send(app.dispatch(AppCommand::Refresh)).unwrap();
        });
        let immediate_result = result_rx.recv_timeout(Duration::from_millis(200));
        allow_disk_commit.wait();
        publisher.join().unwrap().unwrap();
        assert!(
            immediate_result.is_ok(),
            "Stop submission must not wait for disk commit"
        );
        let view = immediate_result.unwrap().unwrap();
        assert_eq!(view.active_job, Some((job_id, JobState::Finalizing)));
        assert!(
            view.message
                .as_deref()
                .is_some_and(|message| message.contains("trop tardif"))
        );
        assert!(matches!(stops.try_recv(), Err(TryRecvError::Empty)));
        assert_eq!(fs::read(&current_pointer).unwrap(), b"manifest.json\n");
        finish_ui_tx.send(()).unwrap();
        let complete = complete_rx
            .recv_timeout(Duration::from_secs(1))
            .unwrap()
            .unwrap();
        assert_eq!(complete.active_job, Some((job_id, JobState::Complete)));
        assert_eq!(gate.0.load(Ordering::Acquire), GATE_COMMITTED);
        ui.join().unwrap();
        fs::remove_file(current_pointer).unwrap();
        fs::remove_dir(commit_directory).unwrap();
    }
}

use std::time::{SystemTime, UNIX_EPOCH};
use whisper_adapters::{
    queue_store::{QueueStatus, QueueStore},
    recovery,
};
use whisper_core::{
    ComputeChoice, Generation, JobConfig, JobId, LanguageChoice,
    ports::{ImportQueueStatus, ImportRequest},
};

fn request(job: u128, source: &str) -> ImportRequest {
    ImportRequest {
        job_id: JobId(job),
        generation: Generation::first(),
        source_path: source.into(),
        source_sha256: Some([0; 32]),
        source_samples: Some(1),
        model_path: "model.bin".into(),
        model_sha256: [0; 32],
        destination: String::new(),
        config: JobConfig {
            language: LanguageChoice::Manual("fr".into()),
            compute: ComputeChoice::Cpu,
        },
    }
}

#[test]
fn queue_ack_replays_fifo_and_running_work_recovers_without_launch() {
    let root = std::env::temp_dir().join(format!(
        "whisper-l02-queue-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    let source_path = root.join("source.mp3");
    std::fs::create_dir_all(&root).unwrap();
    std::fs::write(&source_path, b"source stays intact").unwrap();
    let source_before = std::fs::read(&source_path).unwrap();
    let mut first = request(1, &source_path.to_string_lossy());
    first.destination = root.to_string_lossy().into_owned();
    let mut second = request(2, "two.wav");
    second.destination = root.to_string_lossy().into_owned();
    let mut queue = QueueStore::open(&root).unwrap();
    let mut unidentified = request(9, "unidentified.mp3");
    unidentified.source_sha256 = None;
    assert!(queue.enqueue(unidentified).is_err());
    let first_entry = queue.enqueue(first).unwrap();
    queue.enqueue(second).unwrap();
    assert_eq!(
        queue
            .entries()
            .iter()
            .map(|entry| entry.sequence)
            .collect::<Vec<_>>(),
        [1, 2]
    );
    queue
        .set_status(
            first_entry.request.job_id,
            first_entry.request.generation,
            QueueStatus::Running,
        )
        .unwrap();

    use std::io::Write;
    let queue_path = root.join("transcriptions").join("queue.jsonl");
    std::fs::OpenOptions::new()
        .append(true)
        .open(&queue_path)
        .unwrap()
        .write_all(b"{\"op\":\"upsert\",\"version\":")
        .unwrap();

    let restored = recovery::scan(&root).unwrap();
    assert_eq!(restored.queue[0].status, ImportQueueStatus::Interrupted);
    assert_eq!(restored.queue[1].status, ImportQueueStatus::AwaitingChoice);
    let reopened = QueueStore::open(&root).unwrap();
    assert_eq!(reopened.entries(), restored.queue);
    assert_eq!(
        recovery::scan(&root).unwrap(),
        restored,
        "recovery scan is idempotent"
    );
    assert!(
        std::fs::read(&queue_path).unwrap().ends_with(b"\n"),
        "an unacknowledged partial tail is removed before the next durable append"
    );
    let mut queue = QueueStore::open(&root).unwrap();
    let mut resumed_request = first_entry.request.clone();
    resumed_request.generation = resumed_request.generation.next().unwrap();
    let resumed = queue
        .resume_interrupted(
            first_entry.request.job_id,
            first_entry.request.generation,
            resumed_request.clone(),
        )
        .unwrap();
    assert_eq!(
        resumed.sequence, first_entry.sequence,
        "resume preserves FIFO order"
    );
    assert_eq!(resumed.request.generation, resumed_request.generation);
    assert_eq!(resumed.status, QueueStatus::Running);
    assert!(
        queue
            .remove(resumed.request.job_id, resumed.request.generation)
            .is_err()
    );
    queue
        .set_status(
            resumed.request.job_id,
            resumed.request.generation,
            QueueStatus::Interrupted,
        )
        .unwrap();
    queue
        .remove(resumed.request.job_id, resumed.request.generation)
        .unwrap();
    assert_eq!(std::fs::read(&source_path).unwrap(), source_before);
    std::fs::remove_dir_all(root).unwrap();
}

#[test]
fn resume_validation_rejects_later_fifo_row_without_advancing_any_generation() {
    let root = std::env::temp_dir().join(format!(
        "whisper-l02-resume-fifo-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    std::fs::create_dir_all(&root).unwrap();
    let mut first = request(31, "first.wav");
    first.destination = root.to_string_lossy().into_owned();
    let mut second = request(32, "second.wav");
    second.destination = root.to_string_lossy().into_owned();
    let mut queue = QueueStore::open(&root).unwrap();
    let first_entry = queue.enqueue(first.clone()).unwrap();
    let second_entry = queue.enqueue(second.clone()).unwrap();
    queue
        .set_status(first.job_id, first.generation, QueueStatus::Interrupted)
        .unwrap();
    queue
        .set_status(second.job_id, second.generation, QueueStatus::Interrupted)
        .unwrap();
    let mut later_generation = second.clone();
    later_generation.generation = second.generation.next().unwrap();
    let before_refusal = queue.entries();
    assert!(
        queue
            .validate_resume(second.job_id, second.generation, &later_generation)
            .unwrap_err()
            .contains("FIFO")
    );
    assert_eq!(QueueStore::open(&root).unwrap().entries(), before_refusal);
    let next_generation_dir = root
        .join("transcriptions")
        .join(format!("{:032x}", second.job_id.0))
        .join(later_generation.generation.get().to_string());
    assert!(
        !next_generation_dir.exists(),
        "FIFO refusal creates no pending generation"
    );

    let mut first_next = first.clone();
    first_next.generation = first.generation.next().unwrap();
    queue
        .validate_resume(first.job_id, first.generation, &first_next)
        .unwrap();
    let resumed = queue
        .resume_interrupted(first.job_id, first.generation, first_next.clone())
        .unwrap();
    assert_eq!(resumed.sequence, first_entry.sequence);
    assert_eq!(resumed.request.generation, first_next.generation);
    assert_eq!(QueueStore::open(&root).unwrap().entries()[0], resumed);
    assert_eq!(second_entry.sequence, 2);
    std::fs::remove_dir_all(root).unwrap();
}

use crate::domain::{Generation, JobConfig, JobId, JobState};
use crate::ports::{
    ArchiveHistoryItem, ImportEffect, ImportEvent, ImportIoPort, ImportQueueEntry, ImportRequest,
    PortError,
};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct CommandIdentity {
    pub job_id: JobId,
    pub generation: Generation,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum AppCommand {
    Refresh,
    StartImport {
        request: ImportRequest,
    },
    EnqueueImport {
        request: ImportRequest,
    },
    ProcessQueued {
        request: ImportRequest,
    },
    ResumeInterrupted {
        request: ImportRequest,
    },
    RemoveQueued {
        job_id: JobId,
        generation: Generation,
    },
    StartLive {
        job_id: JobId,
        generation: Generation,
        config: JobConfig,
    },
    Stop {
        job_id: JobId,
        generation: Generation,
    },
    Quit {
        job_id: JobId,
        generation: Generation,
    },
    ScanHistory {
        destination: String,
    },
}

impl AppCommand {
    pub fn identity(&self) -> Option<CommandIdentity> {
        match self {
            Self::Refresh => None,
            Self::StartLive {
                job_id, generation, ..
            }
            | Self::Stop { job_id, generation }
            | Self::Quit { job_id, generation } => Some(CommandIdentity {
                job_id: *job_id,
                generation: *generation,
            }),
            Self::StartImport { request } | Self::EnqueueImport { request } => {
                Some(CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                })
            }
            Self::ProcessQueued { request } | Self::ResumeInterrupted { request } => {
                Some(CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                })
            }
            Self::RemoveQueued { job_id, generation } => Some(CommandIdentity {
                job_id: *job_id,
                generation: *generation,
            }),
            Self::ScanHistory { .. } => None,
        }
    }

    pub fn targets(&self, job_id: JobId, generation: Generation) -> bool {
        self.identity() == Some(CommandIdentity { job_id, generation })
    }
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct AppView {
    pub active_job: Option<(JobId, JobState)>,
    pub queued_jobs: usize,
    pub message: Option<String>,
    pub progress: Option<(u64, u64)>,
    pub last_result: Option<String>,
    pub history: Vec<ArchiveHistoryItem>,
    pub queue: Vec<ImportQueueEntry>,
    pub history_scan_pending: bool,
    pub queue_scan_pending: bool,
}

/// Owns queue admission and import lifecycle. Adapters only execute effects.
pub struct ImportApplication<P> {
    io: P,
    view: AppView,
    active: Option<CommandIdentity>,
    request: Option<ImportRequest>,
    next_sequence: u64,
    pending_persistence: usize,
    pending_enqueues: Vec<CommandIdentity>,
    ended_at: Option<u64>,
    stopping: Option<CommandIdentity>,
    max_segment_offset: u64,
    final_source_samples: Option<u64>,
}

impl<P: ImportIoPort> ImportApplication<P> {
    pub fn new(io: P) -> Self {
        Self {
            io,
            view: AppView::default(),
            active: None,
            request: None,
            next_sequence: 0,
            pending_persistence: 0,
            pending_enqueues: Vec::new(),
            ended_at: None,
            stopping: None,
            max_segment_offset: 0,
            final_source_samples: None,
        }
    }

    fn fail(&mut self, error: PortError) -> ApplicationError {
        self.view.message = Some(format!("Import indisponible : {error:?}"));
        ApplicationError::PortUnavailable
    }

    fn poll_once(&mut self) -> Result<(), ApplicationError> {
        let Some(event) = self.io.poll().map_err(|e| self.fail(e))? else {
            return Ok(());
        };
        match &event {
            ImportEvent::History(history) => {
                self.view.history = history.clone();
                self.view.history_scan_pending = false;
                return Ok(());
            }
            ImportEvent::Queue(queue) => {
                self.view.queue_scan_pending = false;
                let acknowledged = self
                    .pending_enqueues
                    .iter()
                    .filter(|identity| {
                        queue.iter().any(|entry| {
                            entry.request.job_id == identity.job_id
                                && entry.request.generation == identity.generation
                        })
                    })
                    .count();
                self.pending_enqueues.retain(|identity| {
                    !queue.iter().any(|entry| {
                        entry.request.job_id == identity.job_id
                            && entry.request.generation == identity.generation
                    })
                });
                if acknowledged > 0 {
                    self.view.message = Some(format!(
                        "{acknowledged} import(s) ajouté(s) à la file durable. Choisissez Traiter pour les démarrer."
                    ));
                }
                self.view.queued_jobs = queue.len();
                self.view.queue = queue.clone();
                return Ok(());
            }
            ImportEvent::Failed {
                job_id, message, ..
            } if *job_id == JobId(0) && self.view.queue_scan_pending => {
                self.view.queue_scan_pending = false;
                self.view.message = Some(format!("File durable indisponible : {message}"));
                return Ok(());
            }
            _ => {}
        }
        let (job_id, generation) = event.identity();
        let identity = CommandIdentity { job_id, generation };
        let enqueue_failed = matches!(
            &event,
            ImportEvent::Failed { .. } if self.pending_enqueues.contains(&identity)
        );
        if self.active != Some(identity)
            && !(matches!(
                event,
                ImportEvent::Stopped { .. } | ImportEvent::Failed { .. }
            ) && self.stopping == Some(identity))
            && !enqueue_failed
        {
            return Ok(());
        }
        match event {
            ImportEvent::History(_) => {
                unreachable!("non-lifecycle events are handled before job admission")
            }
            ImportEvent::Queue(_) => unreachable!("queue events are handled before job admission"),
            ImportEvent::ResumeCheckpoint {
                confirmed_segments,
                confirmed_offset,
                ..
            } => {
                self.next_sequence = confirmed_segments
                    .checked_add(1)
                    .ok_or(ApplicationError::InvalidCommand)?;
                self.max_segment_offset = confirmed_offset;
            }
            ImportEvent::Prepared(request) => {
                if request.source_sha256.is_none()
                    || request.source_samples.is_none_or(|samples| samples == 0)
                {
                    return Err(ApplicationError::InvalidCommand);
                }
                let Some(accepted) = self.request.as_ref() else {
                    return Err(ApplicationError::InvalidCommand);
                };
                let mut expected = accepted.clone();
                expected.source_sha256 = request.source_sha256;
                expected.source_samples = request.source_samples;
                if expected != request {
                    return Err(ApplicationError::InvalidCommand);
                }
                self.request = Some(request.clone());
                self.io
                    .submit(ImportEffect::StartWorker(request))
                    .map_err(|e| self.fail(e))?;
                self.view.active_job = Some((job_id, JobState::Preparing));
                self.view.message = Some("Source vérifiée ; démarrage du moteur CPU…".into());
            }
            ImportEvent::Ready { backend, .. } => {
                self.view.active_job = Some((job_id, JobState::Running));
                self.view.message = Some(format!("Moteur actif : {backend}"));
            }
            ImportEvent::Progress {
                completed_samples,
                total_samples,
                ..
            } => {
                let source_samples = self
                    .request
                    .as_ref()
                    .and_then(|request| request.source_samples);
                if source_samples.is_none_or(|limit| completed_samples > limit)
                    || (total_samples > 0
                        && (completed_samples != total_samples
                            || Some(total_samples) != source_samples))
                {
                    return Err(ApplicationError::InvalidCommand);
                }
                if total_samples > 0 {
                    self.final_source_samples = Some(total_samples);
                }
                self.view.progress = Some((completed_samples, total_samples));
            }
            ImportEvent::Segment(segment) => {
                if segment.segment_id.0 != self.next_sequence
                    || segment.range.sample_rate_hz != 16_000
                    || segment.range.start_sample >= segment.range.end_sample
                    || self
                        .request
                        .as_ref()
                        .and_then(|request| request.source_samples)
                        .is_none_or(|limit| segment.range.end_sample > limit)
                {
                    return Err(ApplicationError::InvalidCommand);
                }
                self.max_segment_offset = self.max_segment_offset.max(segment.range.end_sample);
                self.next_sequence = self
                    .next_sequence
                    .checked_add(1)
                    .ok_or(ApplicationError::InvalidCommand)?;
                self.io
                    .submit(ImportEffect::PersistSegment(segment))
                    .map_err(|e| self.fail(e))?;
                self.pending_persistence += 1;
            }
            ImportEvent::Persisted { sequence, .. } => {
                self.pending_persistence = self.pending_persistence.saturating_sub(1);
                if sequence >= self.next_sequence {
                    return Err(ApplicationError::InvalidCommand);
                }
                self.maybe_publish(job_id, generation)?;
            }
            ImportEvent::End {
                last_sequence,
                last_offset,
                ..
            } => {
                if last_sequence != self.next_sequence.saturating_sub(1)
                    || last_offset == 0
                    || self.final_source_samples != Some(last_offset)
                    || self
                        .request
                        .as_ref()
                        .and_then(|request| request.source_samples)
                        != Some(last_offset)
                    || self.max_segment_offset > last_offset
                {
                    return Err(ApplicationError::InvalidCommand);
                }
                self.ended_at = Some(last_sequence);
                self.maybe_publish(job_id, generation)?;
            }
            ImportEvent::Published { .. } => {
                self.view.active_job = Some((job_id, JobState::Complete));
                self.view.last_result = Some("Transcription publiée et vérifiée".into());
                self.view.message = None;
                self.active = None;
            }
            ImportEvent::Failed { message, .. } => {
                if self.pending_enqueues.contains(&identity) {
                    self.pending_enqueues.retain(|pending| *pending != identity);
                    self.view.message = Some(message);
                } else if self.stopping == Some(identity) {
                    self.view.active_job = Some((job_id, JobState::Cancelled));
                    self.view.message =
                        Some(format!("Arrêt confirmé; archive conservée ({message})."));
                    self.active = None;
                    self.stopping = None;
                } else {
                    self.view.active_job = Some((job_id, JobState::Recoverable));
                    self.view.message = Some(message);
                    self.active = None;
                }
            }
            ImportEvent::Stopped { .. } => {
                self.view.active_job = Some((job_id, JobState::Cancelled));
                self.view.message =
                    Some("Import arrêté ; la source et l’archive pending sont conservées.".into());
                self.active = None;
                self.stopping = None;
                self.ended_at = None;
                self.pending_persistence = 0;
            }
        }
        Ok(())
    }

    fn maybe_publish(
        &mut self,
        job_id: JobId,
        generation: Generation,
    ) -> Result<(), ApplicationError> {
        if self.pending_persistence == 0
            && let Some(last_sequence) = self.ended_at
        {
            self.io
                .submit(ImportEffect::Publish {
                    job_id,
                    generation,
                    last_sequence,
                })
                .map_err(|e| self.fail(e))?;
            self.ended_at = None;
            self.view.active_job = Some((job_id, JobState::Finalizing));
        }
        Ok(())
    }
}

impl<P: ImportIoPort> Application for ImportApplication<P> {
    fn dispatch(&mut self, command: AppCommand) -> Result<AppView, ApplicationError> {
        match command {
            AppCommand::Refresh => self.poll_once()?,
            AppCommand::ScanHistory { destination } => {
                self.io
                    .submit(ImportEffect::ScanHistory {
                        destination: destination.clone(),
                    })
                    .map_err(|e| self.fail(e))?;
                self.io
                    .submit(ImportEffect::ScanQueue { destination })
                    .map_err(|e| self.fail(e))?;
                self.view.history_scan_pending = true;
                self.view.queue_scan_pending = true;
            }
            AppCommand::RemoveQueued { job_id, generation } => {
                self.io
                    .submit(ImportEffect::RemoveQueued {
                        job_id,
                        generation,
                        destination: self
                            .view
                            .queue
                            .iter()
                            .find(|item| {
                                item.request.job_id == job_id
                                    && item.request.generation == generation
                            })
                            .map(|item| item.request.destination.clone())
                            .ok_or(ApplicationError::InvalidCommand)?,
                    })
                    .map_err(|e| self.fail(e))?;
            }
            AppCommand::StartImport { request } => {
                if self.active.is_some() {
                    return Err(ApplicationError::InvalidCommand);
                }
                let identity = CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                };
                self.io
                    .submit(ImportEffect::Prepare(request.clone()))
                    .map_err(|e| self.fail(e))?;
                self.request = Some(request);
                self.active = Some(identity);
                self.stopping = None;
                self.next_sequence = 1;
                self.pending_persistence = 0;
                self.ended_at = None;
                self.max_segment_offset = 0;
                self.final_source_samples = None;
                self.view.progress = None;
                self.view.active_job = Some((identity.job_id, JobState::Preparing));
                self.view.message = Some("Vérification de la source et du modèle…".into());
            }
            AppCommand::EnqueueImport { request } => {
                let identity = CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                };
                self.io
                    .submit(ImportEffect::Enqueue(request))
                    .map_err(|e| self.fail(e))?;
                self.pending_enqueues.push(identity);
                self.view.message =
                    Some("Vérification de la source et ajout à la file durable en cours…".into());
            }
            AppCommand::ProcessQueued { request } => {
                if self.active.is_some() {
                    return Err(ApplicationError::InvalidCommand);
                }
                let identity = CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                };
                self.io
                    .submit(ImportEffect::ProcessQueued(request.clone()))
                    .map_err(|e| self.fail(e))?;
                self.request = Some(request);
                self.active = Some(identity);
                self.stopping = None;
                self.next_sequence = 1;
                self.pending_persistence = 0;
                self.ended_at = None;
                self.max_segment_offset = 0;
                self.final_source_samples = None;
                self.view.progress = None;
                self.view.active_job = Some((identity.job_id, JobState::Queued));
                self.view.message = Some("Vérification du choix explicite et préparation…".into());
            }
            AppCommand::ResumeInterrupted { request } => {
                if self.active.is_some() {
                    return Err(ApplicationError::InvalidCommand);
                }
                let previous = request;
                let mut resumed = previous.clone();
                resumed.generation = previous
                    .generation
                    .next()
                    .ok_or(ApplicationError::InvalidCommand)?;
                let identity = CommandIdentity {
                    job_id: resumed.job_id,
                    generation: resumed.generation,
                };
                self.io
                    .submit(ImportEffect::ResumeInterrupted {
                        previous: Box::new(previous),
                        request: resumed.clone(),
                    })
                    .map_err(|e| self.fail(e))?;
                self.request = Some(resumed);
                self.active = Some(identity);
                self.stopping = None;
                self.next_sequence = 1;
                self.pending_persistence = 0;
                self.ended_at = None;
                self.max_segment_offset = 0;
                self.final_source_samples = None;
                self.view.progress = None;
                self.view.active_job = Some((identity.job_id, JobState::Queued));
                self.view.message = Some(
                    "Reprise confirmée : vérification du préfixe durable avant recalcul…".into(),
                );
            }
            AppCommand::Stop { job_id, generation } => {
                if self.active != Some(CommandIdentity { job_id, generation }) {
                    return Err(ApplicationError::InvalidCommand);
                }
                let next = generation.next().ok_or(ApplicationError::InvalidCommand)?;
                match self.io.submit(ImportEffect::Stop { job_id, generation }) {
                    Ok(()) => {
                        self.stopping = Some(CommandIdentity { job_id, generation });
                        self.active = Some(CommandIdentity {
                            job_id,
                            generation: next,
                        });
                    }
                    Err(PortError::Committing) => {
                        self.view.active_job = Some((job_id, JobState::Finalizing));
                        self.view.message = Some(
                            "Publication en cours ; l’arrêt est trop tardif. Attendez sa fin."
                                .into(),
                        );
                        return Ok(self.view.clone());
                    }
                    Err(error) => return Err(self.fail(error)),
                }
                self.view.active_job = Some((job_id, JobState::Cancelling));
            }
            _ => return Err(ApplicationError::InvalidCommand),
        }
        Ok(self.view.clone())
    }

    fn view(&self) -> AppView {
        self.view.clone()
    }
}

impl ImportEvent {
    fn identity(&self) -> (JobId, Generation) {
        match self {
            Self::Ready {
                job_id, generation, ..
            }
            | Self::Progress {
                job_id, generation, ..
            }
            | Self::Persisted {
                job_id, generation, ..
            }
            | Self::End {
                job_id, generation, ..
            }
            | Self::Published { job_id, generation }
            | Self::Failed {
                job_id, generation, ..
            }
            | Self::Stopped { job_id, generation } => (*job_id, *generation),
            Self::ResumeCheckpoint {
                job_id, generation, ..
            } => (*job_id, *generation),
            Self::Prepared(request) => (request.job_id, request.generation),
            Self::History(_) | Self::Queue(_) => (JobId(0), Generation::first()),
            Self::Segment(segment) => (segment.job_id, segment.generation),
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum ApplicationError {
    InvalidCommand,
    PortUnavailable,
    Failed(String),
}

/// Application owns orchestration; concrete infrastructure is supplied by a composition root.
pub trait Application {
    fn dispatch(&mut self, command: AppCommand) -> Result<AppView, ApplicationError>;
    fn view(&self) -> AppView;
}

pub struct AppFacade<A> {
    application: A,
}

impl<A: Application> AppFacade<A> {
    pub fn new(application: A) -> Self {
        Self { application }
    }

    pub fn dispatch(&mut self, command: AppCommand) -> Result<AppView, ApplicationError> {
        self.application.dispatch(command)
    }

    pub fn view(&self) -> AppView {
        self.application.view()
    }
}

#[cfg(test)]
mod tests {
