                request: ImportRequest {
                    job_id,
                    generation,
                    source_path: "source.wav".into(),
                    source_sha256: None,
                    source_samples: None,
                    model_path: "model.bin".into(),
                    model_sha256: [0; 32],
                    destination: "archive".into(),
                    config: config.clone(),
                },
            },
            AppCommand::ProcessQueued {
                request: ImportRequest {
                    job_id,
                    generation,
                    source_path: "source.wav".into(),
                    source_sha256: None,
                    source_samples: None,
                    model_path: "model.bin".into(),
                    model_sha256: [0; 32],
