    #[test]
    fn event_65_backpressures_all_production_stages_then_delivers_in_order() {
        struct WireRuntime {
            worker_events: Receiver<Result<WorkerEvent, PortError>>,
            consumed: Arc<std::sync::atomic::AtomicUsize>,
            shutdown: Receiver<()>,
        }
        impl ServiceRuntime for WireRuntime {
            fn apply_effect(&mut self, _: ImportEffect, _: &mut VecDeque<ImportEvent>) {}

            fn poll_event(&mut self) -> Option<Result<ImportEvent, (JobId, Generation, String)>> {
                match self.worker_events.try_recv() {
                    Ok(Ok(WorkerEvent::Progress {
                        job_id,
                        generation,
                        completed_samples,
                        total_samples,
                        ..
                    })) => {
                        self.consumed.fetch_add(1, Ordering::AcqRel);
                        Some(Ok(ImportEvent::Progress {
                            job_id,
                            generation,
                            completed_samples,
                            total_samples,
                        }))
                    }
                    Ok(Ok(WorkerEvent::Failed {
                        job_id: Some(job_id),
                        generation: Some(generation),
                        message,
                        ..
                    })) => {
                        self.consumed.fetch_add(1, Ordering::AcqRel);
                        Some(Err((job_id, generation, message)))
                    }
                    Ok(Err(error)) => Some(Err((
                        JobId(903),
                        Generation::first(),
                        format!("worker reader: {error:?}"),
                    ))),
                    Ok(Ok(_)) => None,
                    Err(TryRecvError::Empty) => match self.shutdown.try_recv() {
                        Ok(()) => Some(Ok(ImportEvent::History(Vec::new()))),
                        Err(_) => None,
                    },
                    Err(TryRecvError::Disconnected) => match self.shutdown.try_recv() {
                        Ok(()) => Some(Ok(ImportEvent::History(Vec::new()))),
                        Err(_) => None,
                    },
                }
            }
        }

        const BACKLOG: usize = EVENTS_PER_STAGE * 3 + 1;
        const EVENT_COUNT: usize = BACKLOG + 1;
        let job_id = JobId(903);
        let generation = Generation::first();
        let mut wire = Vec::new();
        for completed_samples in 1..=BACKLOG as u64 {
            let envelope = IpcEnvelope::new(WorkerEvent::Progress {
                job_id,
                generation,
                instance_id: 1,
                completed_samples,
                total_samples: EVENT_COUNT as u64,
            });
            serde_json::to_writer(&mut wire, &envelope).unwrap();
            wire.push(b'\n');
        }
        let failure = IpcEnvelope::new(WorkerEvent::Failed {
            job_id: Some(job_id),
            generation: Some(generation),
            instance_id: Some(1),
            code: whisper_core::ipc::WorkerErrorCode::Saturated,
            message: "65th event after bounded backlog".into(),
        });
        serde_json::to_writer(&mut wire, &failure).unwrap();
        wire.push(b'\n');

        let (mut io, effect_rx, stop_rx, app_tx) =
            AsyncImportIo::for_test(Arc::new(PublicationGate::default()));
        let app_capacity_probe = app_tx.clone();
        let (worker_tx, worker_rx) = mpsc::sync_channel(EVENTS_PER_STAGE);
        let consumed = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let consumed_probe = consumed.clone();
        let (shutdown_tx, shutdown_rx) = mpsc::channel();
        let service = thread::spawn(move || {
            service_loop(
                effect_rx,
                stop_rx,
                app_tx,
                WireRuntime {
                    worker_events: worker_rx,
                    consumed,
                    shutdown: shutdown_rx,
                },
            )
        });
        let (reader_done_tx, reader_done_rx) = mpsc::channel();
        let reader = thread::spawn(move || {
            read_events(Cursor::new(wire), worker_tx);
            reader_done_tx.send(()).unwrap();
        });

        let deadline = std::time::Instant::now() + Duration::from_secs(2);
        while consumed_probe.load(Ordering::Acquire) < EVENTS_PER_STAGE * 2 {
            assert!(
                std::time::Instant::now() < deadline,
                "pipeline did not fill"
            );
            thread::sleep(Duration::from_millis(5));
        }
        assert!(matches!(
            app_capacity_probe.try_send(ImportEvent::History(Vec::new())),
            Err(TrySendError::Full(_))
        ));
        assert!(
            matches!(reader_done_rx.try_recv(), Err(mpsc::TryRecvError::Empty)),
            "the wire reader must be backpressured while all 64 backlog slots are occupied"
        );
        drop(app_capacity_probe);

        let mut progress = Vec::with_capacity(BACKLOG);
        let mut visible_failure = None;
        let deadline = std::time::Instant::now() + Duration::from_secs(3);
        while progress.len() + usize::from(visible_failure.is_some()) < EVENT_COUNT {
            assert!(
                std::time::Instant::now() < deadline,
                "drained events were lost"
            );
            match io.poll().unwrap() {
                Some(ImportEvent::Progress {
                    completed_samples, ..
                }) => progress.push(completed_samples),
                Some(ImportEvent::Failed { message, .. }) => visible_failure = Some(message),
                Some(other) => panic!("unexpected event after saturation: {other:?}"),
                None => thread::sleep(Duration::from_millis(1)),
            }
        }
        assert_eq!(progress, (1..=BACKLOG as u64).collect::<Vec<_>>());
        assert_eq!(
            visible_failure.as_deref(),
            Some("65th event after bounded backlog")
        );
        reader_done_rx.recv_timeout(Duration::from_secs(1)).unwrap();
        reader.join().unwrap();
        drop(io);
        shutdown_tx.send(()).unwrap();
        service.join().unwrap();
    }

    #[test]
    fn stop_control_is_admitted_when_effect_queue_is_full() {
        let gate = Arc::new(PublicationGate::default());
        let (mut io, effects, stops, _) = AsyncImportIo::for_test(gate);
        let job_id = JobId(901);
        let generation = Generation::first();
        io.submit(ImportEffect::Prepare(test_request(job_id, generation)))
            .unwrap();
        for index in 0..7 {
            io.submit(ImportEffect::ScanHistory {
                destination: format!("archive-{index}"),
            })
            .unwrap();
        }
        assert_eq!(effects.try_iter().count(), 8);
        io.submit(ImportEffect::Stop { job_id, generation })
            .unwrap();
        assert!(matches!(stops.try_recv(), Ok(ImportEffect::Stop { .. })));
    }

    #[test]
    fn frame_limit_counts_newline_and_rejects_oversize_before_write() {
        let gate = Arc::new(PublicationGate::default());
        let (mut io, _effects, _, _) = AsyncImportIo::for_test(gate);
        let mut low = 0;
        let mut high = MAX_FRAME_BYTES;
        while low < high {
            let middle = (low + high).div_ceil(2);
            let effect = ImportEffect::ScanHistory {
                destination: "x".repeat(middle),
            };
            let encoded_len = serde_json::to_vec(&effect).unwrap().len() + 1;
            if encoded_len <= MAX_FRAME_BYTES {
                low = middle;
            } else {
                high = middle - 1;
            }
        }
        let accepted = ImportEffect::ScanHistory {
            destination: "x".repeat(low),
        };
        assert_eq!(
            serde_json::to_vec(&accepted).unwrap().len() + 1,
            MAX_FRAME_BYTES
        );
        io.submit(accepted).unwrap();
        let rejected = ImportEffect::ScanHistory {
            destination: "x".repeat(low + 1),
        };
        assert_eq!(io.submit(rejected), Err(PortError::InvalidInput));
    }

    #[test]
    fn framed_ipc_rejects_incomplete_oversized_and_v1_messages() {
        let incomplete = b"{\"version\":2".as_slice();
        assert!(read_frame::<IpcEnvelope<WorkerEvent>>(&mut Cursor::new(incomplete)).is_err());

        let oversized = vec![b'x'; MAX_FRAME_BYTES];
        assert!(read_frame::<serde_json::Value>(&mut Cursor::new(oversized)).is_err());

        let v1 = b"{\"version\":1,\"message\":{}}\n".as_slice();
        let envelope = read_frame::<IpcEnvelope<serde_json::Value>>(&mut Cursor::new(v1))
            .unwrap()
            .unwrap();
        assert!(!envelope.is_supported());
    }

    #[test]
    fn worker_eof_without_end_is_reported_as_failure() {
        let (tx, rx) = mpsc::sync_channel(1);
        read_events(Cursor::new(Vec::<u8>::new()), tx);
        assert!(
            matches!(rx.try_recv(), Ok(Err(PortError::Failed(message))) if message.contains("without End"))
        );
    }

    fn test_request(job_id: JobId, generation: Generation) -> ImportRequest {
        ImportRequest {
            job_id,
            generation,
            source_path: "source.wav".into(),
            source_sha256: None,
            source_samples: None,
            model_path: "model.bin".into(),
            model_sha256: [0; 32],
            destination: "archive".into(),
            config: JobConfig {
                language: LanguageChoice::Manual("fr".into()),
                compute: ComputeChoice::Cpu,
            },
        }
    }

    #[test]
    fn stop_during_blocked_commit_returns_promptly_and_reports_finalizing() {
        use std::{
            fs::{self, OpenOptions},
            io::Write,
            sync::{Barrier, mpsc},
            time::{SystemTime, UNIX_EPOCH},
        };

        let gate = Arc::new(PublicationGate::default());
        let (io, effects, stops, event_tx) = AsyncImportIo::for_test(gate.clone());
        let mut app = ImportApplication::new(io);
        let job_id = JobId(88);
        let generation = Generation::first();
        app.dispatch(AppCommand::StartImport {
            request: ImportRequest {
                job_id,
                generation,
                source_path: "fixture.wav".into(),
                source_sha256: None,
                source_samples: None,
                model_path: "model.bin".into(),
                model_sha256: [0; 32],
                destination: "archive".into(),
                config: JobConfig {
                    language: LanguageChoice::Manual("fr".into()),
                    compute: ComputeChoice::Cpu,
                },
            },
        })
        .unwrap();
        assert!(matches!(effects.try_recv(), Ok(ImportEffect::Prepare(_))));
        let commit_directory = std::env::temp_dir().join(format!(
            "whisper-stop-commit-{}-{}",
            std::process::id(),
            SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_nanos()
        ));
        fs::create_dir(&commit_directory).unwrap();
        let staged_pointer = commit_directory.join("CURRENT.tmp");
        let current_pointer = commit_directory.join("CURRENT");

        let commit_entered = Arc::new(Barrier::new(2));
        let allow_disk_commit = Arc::new(Barrier::new(2));
        let publisher = {
            let gate = gate.clone();
            let commit_entered = commit_entered.clone();
            let allow_disk_commit = allow_disk_commit.clone();
            let staged_pointer = staged_pointer.clone();
            let current_pointer = current_pointer.clone();
            thread::spawn(move || {
                gate.commit(|| {
                    commit_entered.wait();
                    allow_disk_commit.wait();
                    let mut file = OpenOptions::new()
                        .write(true)
                        .create_new(true)
                        .open(&staged_pointer)
                        .map_err(|error| error.to_string())?;
                    file.write_all(b"manifest.json\n")
                        .map_err(|error| error.to_string())?;
                    file.sync_all().map_err(|error| error.to_string())?;
                    drop(file);
                    fs::rename(staged_pointer, current_pointer)
                        .map_err(|error| error.to_string())?;
                    Ok(())
                })
            })
        };
        commit_entered.wait();

        let (result_tx, result_rx) = mpsc::channel();
        let (finish_ui_tx, finish_ui_rx) = mpsc::channel();
        let (complete_tx, complete_rx) = mpsc::channel();
        let ui = thread::spawn(move || {
            result_tx
                .send(app.dispatch(AppCommand::Stop { job_id, generation }))
                .unwrap();
            finish_ui_rx.recv().unwrap();
            event_tx
                .send(ImportEvent::Published { job_id, generation })
                .unwrap();
            complete_tx.send(app.dispatch(AppCommand::Refresh)).unwrap();
        });
        let immediate_result = result_rx.recv_timeout(Duration::from_millis(200));
        allow_disk_commit.wait();
        publisher.join().unwrap().unwrap();
        assert!(
            immediate_result.is_ok(),
            "Stop submission must not wait for disk commit"
        );
        let view = immediate_result.unwrap().unwrap();
        assert_eq!(view.active_job, Some((job_id, JobState::Finalizing)));
        assert!(
            view.message
                .as_deref()
                .is_some_and(|message| message.contains("trop tardif"))
        );
        assert!(matches!(stops.try_recv(), Err(TryRecvError::Empty)));
        assert_eq!(fs::read(&current_pointer).unwrap(), b"manifest.json\n");
        finish_ui_tx.send(()).unwrap();
        let complete = complete_rx
            .recv_timeout(Duration::from_secs(1))
            .unwrap()
            .unwrap();
        assert_eq!(complete.active_job, Some((job_id, JobState::Complete)));
        assert_eq!(gate.0.load(Ordering::Acquire), GATE_COMMITTED);
        ui.join().unwrap();
        fs::remove_file(current_pointer).unwrap();
        fs::remove_dir(commit_directory).unwrap();
    }
}

use crate::domain::{Generation, JobConfig, JobId, JobState};
use crate::ports::{
    ArchiveHistoryItem, ImportEffect, ImportEvent, ImportIoPort, ImportQueueEntry, ImportRequest,
    LiveRequest, PortError,
};

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct CommandIdentity {
    pub job_id: JobId,
    pub generation: Generation,
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum AppCommand {
    Refresh,
    StartImport {
        request: ImportRequest,
    },
    EnqueueImport {
        request: ImportRequest,
    },
    ProcessQueued {
        request: ImportRequest,
    },
    ResumeInterrupted {
        request: ImportRequest,
    },
    RemoveQueued {
        job_id: JobId,
        generation: Generation,
    },
    StartLive {
        job_id: JobId,
        generation: Generation,
        config: JobConfig,
    },
    StartLiveConfigured {
        request: LiveRequest,
    },
    Stop {
        job_id: JobId,
        generation: Generation,
    },
    Quit {
        job_id: JobId,
        generation: Generation,
    },
    ScanHistory {
        destination: String,
    },
}

impl AppCommand {
    pub fn identity(&self) -> Option<CommandIdentity> {
        match self {
            Self::Refresh => None,
            Self::StartLive {
                job_id, generation, ..
            }
            | Self::Stop { job_id, generation }
            | Self::Quit { job_id, generation } => Some(CommandIdentity {
                job_id: *job_id,
                generation: *generation,
            }),
            Self::StartImport { request } | Self::EnqueueImport { request } => {
                Some(CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                })
            }
            Self::ProcessQueued { request } | Self::ResumeInterrupted { request } => {
                Some(CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                })
            }
            Self::RemoveQueued { job_id, generation } => Some(CommandIdentity {
                job_id: *job_id,
                generation: *generation,
            }),
            Self::StartLiveConfigured { request } => Some(CommandIdentity {
                job_id: request.job_id,
                generation: request.generation,
            }),
            Self::ScanHistory { .. } => None,
        }
    }

    pub fn targets(&self, job_id: JobId, generation: Generation) -> bool {
        self.identity() == Some(CommandIdentity { job_id, generation })
    }
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct AppView {
    pub active_job: Option<(JobId, JobState)>,
    pub queued_jobs: usize,
    pub message: Option<String>,
    pub progress: Option<(u64, u64)>,
    pub last_result: Option<String>,
    pub history: Vec<ArchiveHistoryItem>,
    pub queue: Vec<ImportQueueEntry>,
    pub history_scan_pending: bool,
    pub queue_scan_pending: bool,
    pub captured_samples: u64,
    pub admitted_samples: u64,
    pub audio_durable_samples: u64,
    pub confirmed_fragment_samples: u64,
    pub speech_samples: u64,
    pub provisional_text: Option<String>,
    pub provisional_sequence: Option<u64>,
    pub provisional_range: Option<crate::domain::SourceRange>,
    pub provisional_captured_at_unix_ms: Option<u64>,
    pub provisional_available_at_unix_ms: Option<u64>,
    pub confirmed_text: Option<String>,
}

/// Owns queue admission and import lifecycle. Adapters only execute effects.
pub struct ImportApplication<P> {
    io: P,
    view: AppView,
    active: Option<CommandIdentity>,
    request: Option<ImportRequest>,
    next_sequence: u64,
    pending_persistence: usize,
    pending_live_segments: std::collections::BTreeMap<u64, crate::ports::WorkerSegment>,
    pending_enqueues: Vec<CommandIdentity>,
    auto_stop_after_speech_samples: Option<u64>,
    ended_at: Option<u64>,
    stopping: Option<CommandIdentity>,
    max_segment_offset: u64,
    final_source_samples: Option<u64>,
}

impl<P: ImportIoPort> ImportApplication<P> {
    pub fn new(io: P) -> Self {
        Self {
            io,
            view: AppView::default(),
            active: None,
            request: None,
            next_sequence: 0,
            pending_persistence: 0,
            pending_live_segments: std::collections::BTreeMap::new(),
            pending_enqueues: Vec::new(),
            auto_stop_after_speech_samples: None,
            ended_at: None,
            stopping: None,
            max_segment_offset: 0,
            final_source_samples: None,
        }
    }

    fn fail(&mut self, error: PortError) -> ApplicationError {
        self.view.message = Some(format!("Import indisponible : {error:?}"));
        ApplicationError::PortUnavailable
    }

    fn poll_once(&mut self) -> Result<(), ApplicationError> {
        let Some(event) = self.io.poll().map_err(|e| self.fail(e))? else {
            return Ok(());
        };
        match &event {
            ImportEvent::History(history) => {
                self.view.history = history.clone();
                self.view.history_scan_pending = false;
                return Ok(());
            }
            ImportEvent::Queue(queue) => {
                self.view.queue_scan_pending = false;
                let acknowledged = self
                    .pending_enqueues
                    .iter()
                    .filter(|identity| {
                        queue.iter().any(|entry| {
                            entry.request.job_id == identity.job_id
                                && entry.request.generation == identity.generation
                        })
                    })
                    .count();
                self.pending_enqueues.retain(|identity| {
                    !queue.iter().any(|entry| {
                        entry.request.job_id == identity.job_id
                            && entry.request.generation == identity.generation
                    })
                });
                if acknowledged > 0 {
                    self.view.message = Some(format!(
                        "{acknowledged} import(s) ajouté(s) à la file durable. Choisissez Traiter pour les démarrer."
                    ));
                }
                self.view.queued_jobs = queue.len();
                self.view.queue = queue.clone();
                return Ok(());
            }
            ImportEvent::Failed {
                job_id, message, ..
            } if *job_id == JobId(0) && self.view.queue_scan_pending => {
                self.view.queue_scan_pending = false;
                self.view.message = Some(format!("File durable indisponible : {message}"));
                return Ok(());
            }
            _ => {}
        }
        let (job_id, generation) = event.identity();
        let identity = CommandIdentity { job_id, generation };
        let enqueue_failed = matches!(
            &event,
            ImportEvent::Failed { .. } if self.pending_enqueues.contains(&identity)
        );
        if self.active != Some(identity)
            && !(matches!(
                event,
                ImportEvent::Stopped { .. } | ImportEvent::Failed { .. }
            ) && self.stopping == Some(identity))
            && !enqueue_failed
        {
            return Ok(());
        }
        if self.stopping == Some(identity)
            && self.request.is_some()
            && matches!(event, ImportEvent::Segment(_))
        {
            return Ok(());
        }
        match event {
            ImportEvent::LiveProvisional {
                segment,
                captured_at_unix_ms,
                available_at_unix_ms,
            } => {
                let sequence = segment.segment_id.0;
                self.view.provisional_text = Some(segment.text.clone());
                self.view.provisional_sequence = Some(sequence);
                self.view.provisional_range = Some(segment.range);
                self.view.provisional_captured_at_unix_ms = Some(captured_at_unix_ms);
                self.view.provisional_available_at_unix_ms = Some(available_at_unix_ms);
                self.pending_live_segments.insert(sequence, segment.clone());
                self.accept_segment(segment, job_id, generation)?;
            }
            ImportEvent::LiveCounters {
                captured_samples,
                admitted_samples,
                audio_durable_samples,
                confirmed_fragment_samples,
                speech_samples,
                diagnostic,
                ..
            } => {
                self.view.captured_samples = captured_samples;
                self.view.admitted_samples = admitted_samples;
                self.view.audio_durable_samples = audio_durable_samples;
                self.view.confirmed_fragment_samples = confirmed_fragment_samples;
                self.view.speech_samples = speech_samples;
                if let Some(message) = diagnostic {
                    self.view.message = Some(message);
                }
                if self.stopping.is_none()
                    && self
                        .auto_stop_after_speech_samples
                        .is_some_and(|limit| speech_samples >= limit)
                {
                    self.io
                        .submit(ImportEffect::Stop { job_id, generation })
                        .map_err(|e| self.fail(e))?;
                    self.stopping = Some(identity);
                    self.view.active_job = Some((
                        job_id,
                        if self.request.is_none() {
                            JobState::Draining
                        } else {
                            JobState::Cancelling
                        },
                    ));
                    self.view.message =
                        Some("Durée de parole atteinte ; finalisation du passage…".into());
                }
            }
            ImportEvent::LiveFinalizing { .. } => {
                self.view.active_job = Some((job_id, JobState::Finalizing));
            }
            ImportEvent::History(_) => {
                unreachable!("non-lifecycle events are handled before job admission")
            }
            ImportEvent::Queue(_) => unreachable!("queue events are handled before job admission"),
            ImportEvent::ResumeCheckpoint {
                confirmed_segments,
                confirmed_offset,
                ..
            } => {
                self.next_sequence = confirmed_segments
                    .checked_add(1)
                    .ok_or(ApplicationError::InvalidCommand)?;
                self.max_segment_offset = confirmed_offset;
            }
            ImportEvent::Prepared(request) => {
                if request.source_sha256.is_none()
                    || request.source_samples.is_none_or(|samples| samples == 0)
                {
                    return Err(ApplicationError::InvalidCommand);
                }
                let Some(accepted) = self.request.as_ref() else {
                    return Err(ApplicationError::InvalidCommand);
                };
                let mut expected = accepted.clone();
                expected.source_sha256 = request.source_sha256;
                expected.source_samples = request.source_samples;
                if expected != request {
                    return Err(ApplicationError::InvalidCommand);
                }
                self.request = Some(request.clone());
                if self.stopping != Some(identity) {
                    self.io
                        .submit(ImportEffect::StartWorker(request))
                        .map_err(|e| self.fail(e))?;
                    self.view.active_job = Some((job_id, JobState::Preparing));
                    self.view.message = Some("Source vérifiée ; démarrage du moteur CPU…".into());
                }
            }
            ImportEvent::Ready { backend, .. } => {
                if self.stopping != Some(identity) {
                    self.view.active_job = Some((
                        job_id,
                        if self.request.is_none() {
                            JobState::Capturing
                        } else {
                            JobState::Running
                        },
                    ));
                    self.view.message = Some(format!("Moteur actif : {backend}"));
                }
            }
            ImportEvent::Progress {
                completed_samples,
                total_samples,
                ..
            } => {
                let source_samples = self
                    .request
                    .as_ref()
                    .and_then(|request| request.source_samples);
                if source_samples.is_none_or(|limit| completed_samples > limit)
                    || (total_samples > 0
                        && (completed_samples != total_samples
                            || Some(total_samples) != source_samples))
                {
                    return Err(ApplicationError::InvalidCommand);
                }
                if total_samples > 0 {
                    self.final_source_samples = Some(total_samples);
                }
                self.view.progress = Some((completed_samples, total_samples));
            }
            ImportEvent::Segment(segment) => {
                self.accept_segment(segment, job_id, generation)?;
            }
            ImportEvent::Persisted { sequence, .. } => {
                self.pending_persistence = self.pending_persistence.saturating_sub(1);
                if sequence >= self.next_sequence {
                    return Err(ApplicationError::InvalidCommand);
                }
                if self.request.is_none() {
                    self.view.confirmed_fragment_samples = self
                        .view
                        .confirmed_fragment_samples
                        .max(self.max_segment_offset);
                    if let Some(segment) = self.pending_live_segments.remove(&sequence) {
                        self.view.confirmed_text = Some(segment.text);
                        if self.view.provisional_sequence == Some(sequence) {
                            self.view.provisional_text = None;
                            self.view.provisional_sequence = None;
                            self.view.provisional_range = None;
                            self.view.provisional_captured_at_unix_ms = None;
                            self.view.provisional_available_at_unix_ms = None;
                        }
                    }
                }
                self.maybe_publish(job_id, generation)?;
            }
            ImportEvent::End {
                last_sequence,
                last_offset,
                ..
            } => {
                if last_sequence != self.next_sequence.saturating_sub(1)
                    || last_offset == 0
                    || self.final_source_samples != Some(last_offset)
                    || self
                        .request
                        .as_ref()
                        .and_then(|request| request.source_samples)
                        != Some(last_offset)
                    || self.max_segment_offset > last_offset
                {
                    return Err(ApplicationError::InvalidCommand);
                }
                self.ended_at = Some(last_sequence);
                self.maybe_publish(job_id, generation)?;
            }
            ImportEvent::Published { .. } => {
                if self.stopping == Some(identity) && self.request.is_some() {
                    self.view.active_job = Some((job_id, JobState::Cancelling));
                } else {
                    self.view.active_job = Some((job_id, JobState::Complete));
                    self.view.last_result = Some("Transcription publiée et vérifiée".into());
                    self.view.message = None;
                    self.active = None;
                    self.stopping = None;
                    self.view.provisional_text = None;
                    self.view.provisional_sequence = None;
                    self.view.provisional_range = None;
                    self.view.provisional_captured_at_unix_ms = None;
                    self.view.provisional_available_at_unix_ms = None;
                }
            }
            ImportEvent::Failed { message, .. } => {
                if self.pending_enqueues.contains(&identity) {
                    self.pending_enqueues.retain(|pending| *pending != identity);
                    self.view.message = Some(message);
                } else if self.stopping == Some(identity) && self.request.is_some() {
                    self.view.active_job = Some((job_id, JobState::Cancelled));
                    self.view.message =
                        Some(format!("Arrêt confirmé; archive conservée ({message})."));
                    self.active = None;
                    self.stopping = None;
                } else {
                    self.view.active_job = Some((job_id, JobState::Recoverable));
                    self.view.message = Some(message);
                    self.active = None;
                    self.stopping = None;
                }
            }
            ImportEvent::Stopped { .. } => {
                self.view.active_job = Some((job_id, JobState::Cancelled));
                self.view.message =
                    Some("Arrêt confirmé ; la source et l’archive pending sont conservées.".into());
                self.active = None;
                self.stopping = None;
                self.ended_at = None;
                self.pending_persistence = 0;
            }
        }
        Ok(())
    }

    fn maybe_publish(
        &mut self,
        job_id: JobId,
        generation: Generation,
    ) -> Result<(), ApplicationError> {
        if self.pending_persistence == 0
            && let Some(last_sequence) = self.ended_at
        {
            self.io
                .submit(ImportEffect::Publish {
                    job_id,
                    generation,
                    last_sequence,
                })
                .map_err(|e| self.fail(e))?;
            self.ended_at = None;
            self.view.active_job = Some((job_id, JobState::Finalizing));
        }
        Ok(())
    }

    fn accept_segment(
        &mut self,
        segment: crate::ports::WorkerSegment,
        _job_id: crate::domain::JobId,
        _generation: crate::domain::Generation,
    ) -> Result<(), ApplicationError> {
        if segment.segment_id.0 != self.next_sequence
            || segment.range.sample_rate_hz != 16_000
            || segment.range.start_sample >= segment.range.end_sample
            || self
                .request
                .as_ref()
                .and_then(|request| request.source_samples)
                .is_some_and(|limit| segment.range.end_sample > limit)
        {
            return Err(ApplicationError::InvalidCommand);
        }
        self.max_segment_offset = self.max_segment_offset.max(segment.range.end_sample);
        self.next_sequence = self
            .next_sequence
            .checked_add(1)
            .ok_or(ApplicationError::InvalidCommand)?;
        self.io
            .submit(ImportEffect::PersistSegment(segment))
            .map_err(|e| self.fail(e))?;
        self.pending_persistence += 1;
        Ok(())
    }
}

impl<P: ImportIoPort> Application for ImportApplication<P> {
    fn dispatch(&mut self, command: AppCommand) -> Result<AppView, ApplicationError> {
        match command {
            AppCommand::Refresh => self.poll_once()?,
            AppCommand::ScanHistory { destination } => {
                self.io
                    .submit(ImportEffect::ScanHistory {
                        destination: destination.clone(),
                    })
                    .map_err(|e| self.fail(e))?;
                self.io
                    .submit(ImportEffect::ScanQueue { destination })
                    .map_err(|e| self.fail(e))?;
                self.view.history_scan_pending = true;
                self.view.queue_scan_pending = true;
            }
            AppCommand::RemoveQueued { job_id, generation } => {
                self.io
                    .submit(ImportEffect::RemoveQueued {
                        job_id,
                        generation,
                        destination: self
                            .view
                            .queue
                            .iter()
                            .find(|item| {
                                item.request.job_id == job_id
                                    && item.request.generation == generation
                            })
                            .map(|item| item.request.destination.clone())
                            .ok_or(ApplicationError::InvalidCommand)?,
                    })
                    .map_err(|e| self.fail(e))?;
            }
            AppCommand::StartLiveConfigured { request } => {
                if self.active.is_some() {
                    return Err(ApplicationError::InvalidCommand);
                }
                let identity = CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                };
                self.auto_stop_after_speech_samples = request
                    .auto_stop_after_speech_samples
                    .filter(|limit| *limit > 0);
                self.io
                    .submit(ImportEffect::StartLive(request))
                    .map_err(|e| self.fail(e))?;
                self.request = None;
                self.active = Some(identity);
                self.stopping = None;
                self.next_sequence = 1;
                self.pending_persistence = 0;
                self.pending_live_segments.clear();
                self.max_segment_offset = 0;
                self.ended_at = None;
                self.final_source_samples = None;
                self.view.progress = None;
                self.view.active_job = Some((identity.job_id, JobState::Preparing));
                self.view.captured_samples = 0;
                self.view.admitted_samples = 0;
                self.view.audio_durable_samples = 0;
                self.view.confirmed_fragment_samples = 0;
                self.view.speech_samples = 0;
                self.view.provisional_text = None;
                self.view.provisional_sequence = None;
                self.view.provisional_range = None;
                self.view.provisional_captured_at_unix_ms = None;
                self.view.provisional_available_at_unix_ms = None;
                self.view.confirmed_text = None;
                self.view.message = Some("Préparation du staging durable et du worker CPU…".into());
            }
            AppCommand::StartImport { request } => {
                if self.active.is_some() {
                    return Err(ApplicationError::InvalidCommand);
                }
                let identity = CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                };
                self.io
                    .submit(ImportEffect::Prepare(request.clone()))
                    .map_err(|e| self.fail(e))?;
                self.request = Some(request);
                self.auto_stop_after_speech_samples = None;
                self.active = Some(identity);
                self.stopping = None;
                self.next_sequence = 1;
                self.pending_persistence = 0;
                self.ended_at = None;
                self.max_segment_offset = 0;
                self.final_source_samples = None;
                self.view.progress = None;
                self.view.active_job = Some((identity.job_id, JobState::Preparing));
                self.view.message = Some("Vérification de la source et du modèle…".into());
            }
            AppCommand::EnqueueImport { request } => {
                let identity = CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                };
                self.io
                    .submit(ImportEffect::Enqueue(request))
                    .map_err(|e| self.fail(e))?;
                self.pending_enqueues.push(identity);
                self.view.message =
                    Some("Vérification de la source et ajout à la file durable en cours…".into());
            }
            AppCommand::ProcessQueued { request } => {
                if self.active.is_some() {
                    return Err(ApplicationError::InvalidCommand);
                }
                let identity = CommandIdentity {
                    job_id: request.job_id,
                    generation: request.generation,
                };
                self.io
                    .submit(ImportEffect::ProcessQueued(request.clone()))
                    .map_err(|e| self.fail(e))?;
                self.request = Some(request);
                self.active = Some(identity);
                self.stopping = None;
                self.next_sequence = 1;
                self.pending_persistence = 0;
                self.ended_at = None;
                self.max_segment_offset = 0;
                self.final_source_samples = None;
                self.view.progress = None;
                self.view.active_job = Some((identity.job_id, JobState::Queued));
                self.view.message = Some("Vérification du choix explicite et préparation…".into());
            }
            AppCommand::ResumeInterrupted { request } => {
                if self.active.is_some() {
                    return Err(ApplicationError::InvalidCommand);
                }
                let previous = request;
                let mut resumed = previous.clone();
                resumed.generation = previous
                    .generation
                    .next()
                    .ok_or(ApplicationError::InvalidCommand)?;
                let identity = CommandIdentity {
                    job_id: resumed.job_id,
                    generation: resumed.generation,
                };
                self.io
                    .submit(ImportEffect::ResumeInterrupted {
                        previous: Box::new(previous),
                        request: resumed.clone(),
                    })
                    .map_err(|e| self.fail(e))?;
                self.request = Some(resumed);
                self.active = Some(identity);
                self.stopping = None;
                self.next_sequence = 1;
                self.pending_persistence = 0;
                self.ended_at = None;
                self.max_segment_offset = 0;
                self.final_source_samples = None;
                self.view.progress = None;
                self.view.active_job = Some((identity.job_id, JobState::Queued));
                self.view.message = Some(
                    "Reprise confirmée : vérification du préfixe durable avant recalcul…".into(),
                );
            }
            AppCommand::Stop { job_id, generation } => {
                if self.active != Some(CommandIdentity { job_id, generation }) {
                    return Err(ApplicationError::InvalidCommand);
                }
                match self.io.submit(ImportEffect::Stop { job_id, generation }) {
                    Ok(()) => {
                        self.stopping = Some(CommandIdentity { job_id, generation });
                    }
                    Err(PortError::Committing) => {
                        self.view.active_job = Some((job_id, JobState::Finalizing));
                        self.view.message = Some(
                            "Publication en cours ; l’arrêt est trop tardif. Attendez sa fin."
                                .into(),
                        );
                        return Ok(self.view.clone());
                    }
                    Err(error) => return Err(self.fail(error)),
                }
                self.view.active_job = Some((
                    job_id,
                    if self.request.is_none() {
                        JobState::Draining
                    } else {
                        JobState::Cancelling
                    },
                ));
            }
            _ => return Err(ApplicationError::InvalidCommand),
        }
        Ok(self.view.clone())
    }

    fn view(&self) -> AppView {
        self.view.clone()
    }
}

impl ImportEvent {
    fn identity(&self) -> (JobId, Generation) {
        match self {
            Self::LiveProvisional { segment, .. } => (segment.job_id, segment.generation),
            Self::LiveCounters {
                job_id, generation, ..
            } => (*job_id, *generation),
            Self::LiveFinalizing { job_id, generation } => (*job_id, *generation),
            Self::Ready {
                job_id, generation, ..
            }
            | Self::Progress {
                job_id, generation, ..
            }
            | Self::Persisted {
                job_id, generation, ..
            }
            | Self::End {
                job_id, generation, ..
            }
            | Self::Published { job_id, generation }
            | Self::Failed {
                job_id, generation, ..
            }
            | Self::Stopped { job_id, generation } => (*job_id, *generation),
            Self::ResumeCheckpoint {
                job_id, generation, ..
            } => (*job_id, *generation),
            Self::Prepared(request) => (request.job_id, request.generation),
            Self::History(_) | Self::Queue(_) => (JobId(0), Generation::first()),
            Self::Segment(segment) => (segment.job_id, segment.generation),
        }
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
pub enum ApplicationError {
    InvalidCommand,
    PortUnavailable,
    Failed(String),
}

/// Application owns orchestration; concrete infrastructure is supplied by a composition root.
pub trait Application {
    fn dispatch(&mut self, command: AppCommand) -> Result<AppView, ApplicationError>;
    fn view(&self) -> AppView;
}

pub struct AppFacade<A> {
    application: A,
}

impl<A: Application> AppFacade<A> {
    pub fn new(application: A) -> Self {
        Self { application }
    }

    pub fn dispatch(&mut self, command: AppCommand) -> Result<AppView, ApplicationError> {
        self.application.dispatch(command)
    }

    pub fn view(&self) -> AppView {
        self.application.view()
    }
}

