const EVENTS_PER_STAGE: usize = 21;
const GATE_IDLE: u8 = 0;
const GATE_ACTIVE: u8 = 1;
const GATE_CANCELLED: u8 = 2;
const GATE_COMMITTING: u8 = 3;
const GATE_COMMITTED: u8 = 4;
static NEXT_INSTANCE: AtomicU64 = AtomicU64::new(1);

