use std::path::PathBuf;
use whisper_adapters::worker_ipc::AsyncImportIo;
use whisper_core::ImportApplication;

pub fn compose() -> ImportApplication<AsyncImportIo> {
    let executable = std::env::current_exe().ok();
    let worker_name = "whisper-worker-cpu.exe";
    let sibling = executable
        .as_ref()
        .and_then(|path| path.parent().map(|parent| parent.join(worker_name)));
    let isolated_cpu = executable.as_ref().and_then(|path| {
        let release = path.parent()?;
        let target = release.parent()?;
        let package_target = target.parent()?;
        Some(
            package_target
                .parent()?
                .join("cpu")
                .join(target.file_name()?)
                .join(release.file_name()?)
                .join(worker_name),
        )
    });
    let worker = [sibling.clone(), isolated_cpu]
        .into_iter()
        .flatten()
        .find(|path| path.is_file())
        .or(sibling)
        .unwrap_or_else(|| PathBuf::from(worker_name));
    ImportApplication::new(AsyncImportIo::start(worker))
}

use eframe::egui;
use std::sync::atomic::{AtomicU64, Ordering};
use whisper_core::{
    AppCommand, AppFacade, AppView, Application, ApplicationError, ComputeChoice, Generation,
    ImportRequest, JobConfig, JobId, JobState, LanguageChoice,
};

const APPROVED_MODEL_SHA256: &str =
    "1fc70f774d38eb169993ac391eea357ef47c88757ef72ee5943879b7e8e2bc69";
static NEXT_JOB: AtomicU64 = AtomicU64::new(1);

pub struct DesktopApp<A> {
    application: AppFacade<A>,
    view: AppView,
    source_path: String,
    model_path: String,
    destination: String,
    manual_language: bool,
    language: String,
    active_identity: Option<(JobId, Generation)>,
    scanned_destination: Option<String>,
    observed_job_state: Option<JobState>,
}

impl<A: Application> DesktopApp<A> {
    pub fn new(application: A) -> Self {
        let application = AppFacade::new(application);
        let view = application.view();
        let model_path = std::env::var("LOCALAPPDATA")
            .map(|path| format!(r"{path}\Programs\WhisperBuildDeps\models\ggml-large-v3-turbo.bin"))
            .unwrap_or_default();
        let destination = std::env::var("USERPROFILE")
            .map(|path| format!(r"{path}\Documents\WhisperTranscriptions"))
            .unwrap_or_default();
        Self {
            application,
            view,
            source_path: String::new(),
            model_path,
            destination,
            manual_language: false,
            language: "fr".into(),
            active_identity: None,
            scanned_destination: None,
            observed_job_state: None,
        }
    }

    fn dispatch(&mut self, command: AppCommand) {
        match self.application.dispatch(command) {
            Ok(view) => self.view = view,
            Err(ApplicationError::Failed(message)) => self.view.message = Some(message),
            Err(error) => self.view.message = Some(format!("Commande impossible : {error:?}")),
        }
    }

    fn start_import(&mut self) {
        let serial = NEXT_JOB.fetch_add(1, Ordering::Relaxed);
        let job_id = JobId(((std::process::id() as u128) << 64) | serial as u128);
        let generation = Generation::first();
        let config = JobConfig {
            language: if self.manual_language {
                LanguageChoice::Manual(self.language.trim().to_owned())
            } else {
                LanguageChoice::Automatic
            },
            compute: ComputeChoice::Cpu,
        };
        self.active_identity = Some((job_id, generation));
        self.dispatch(AppCommand::StartImport {
            request: ImportRequest {
                job_id,
                generation,
                source_path: self.source_path.trim().to_owned(),
                source_sha256: None,
                source_samples: None,
                model_path: self.model_path.trim().to_owned(),
                model_sha256: parse_sha256(APPROVED_MODEL_SHA256),
                destination: self.destination.trim().to_owned(),
                config,
            },
        });
    }
}

impl<A: Application> eframe::App for DesktopApp<A> {
    fn ui(&mut self, ui: &mut egui::Ui, _frame: &mut eframe::Frame) {
        self.dispatch(AppCommand::Refresh);
        let state = self.view.active_job.map(|(_, state)| state);
        if state != self.observed_job_state
            && state.is_some_and(|state| {
                matches!(
                    state,
                    JobState::Complete | JobState::Recoverable | JobState::Cancelled
                )
            })
        {
            self.scanned_destination = None;
        }
        self.observed_job_state = state;
        let busy = self.view.active_job.is_some_and(|(_, state)| {
            matches!(
                state,
                JobState::Preparing
                    | JobState::Running
                    | JobState::Cancelling
                    | JobState::Finalizing
            )
        });
        if !busy {
            self.active_identity = None;
        }
        ui.heading("Whisper — transcription locale");
        ui.label("Import WAV sur le worker CPU avec le modèle D19 approuvé.");

        ui.add_enabled_ui(!busy, |ui| {
            ui.horizontal(|ui| {
                ui.label("Fichier WAV");
                ui.text_edit_singleline(&mut self.source_path);
            });
            ui.horizontal(|ui| {
                ui.label("Modèle local");
                ui.text_edit_singleline(&mut self.model_path);
            });
            ui.horizontal(|ui| {
                ui.label("Dossier des transcriptions");
                ui.text_edit_singleline(&mut self.destination);
            });
            ui.horizontal(|ui| {
                ui.checkbox(&mut self.manual_language, "Langue manuelle");
                if self.manual_language {
                    ui.text_edit_singleline(&mut self.language);
                }
                ui.label("Calcul : CPU");
            });
            let can_start = !self.source_path.trim().is_empty()
                && !self.model_path.trim().is_empty()
                && !self.destination.trim().is_empty()
                && (!self.manual_language || !self.language.trim().is_empty());
            if ui
                .add_enabled(can_start, egui::Button::new("Importer et transcrire"))
                .clicked()
            {
                self.start_import();
            }
        });

        if let Some((job_id, state)) = self.view.active_job {
            ui.separator();
            ui.label(format!("Import {job_id:?} — {state:?}"));
            if let Some((completed, total)) = self.view.progress {
                if total > 0 {
                    ui.add(
                        egui::ProgressBar::new((completed as f32 / total as f32).clamp(0.0, 1.0))
                            .text(format!("{completed} / {total} échantillons")),
                    );
                } else {
                    ui.label(format!(
                        "Progression : {completed} échantillons PCM traités"
                    ));
                }
            }
            if matches!(
                state,
                JobState::Preparing | JobState::Running | JobState::Finalizing
            ) && ui.button("Arrêter l’import").clicked()
                && let Some((job, generation)) = self.active_identity
            {
                self.dispatch(AppCommand::Stop {
                    job_id: job,
                    generation,
                });
            }
        }
        if let Some(message) = &self.view.message {
            ui.colored_label(egui::Color32::LIGHT_RED, message);
        }
        if let Some(result) = &self.view.last_result {
            ui.colored_label(egui::Color32::LIGHT_GREEN, result);
        }

        if self.scanned_destination.as_deref() != Some(self.destination.trim())
            && !self.destination.trim().is_empty()
        {
            self.scanned_destination = Some(self.destination.trim().to_owned());
            self.dispatch(AppCommand::ScanHistory {
                destination: self.destination.trim().to_owned(),
            });
        }
        ui.separator();
        ui.heading("Historique local");
        if self.view.history.is_empty() {
            ui.label("Aucune transcription publiée dans ce dossier.");
        }
        for item in &self.view.history {
            ui.label(format!(
                "{} — job {:?}, génération {} — source {}",
                if item.complete {
                    "Terminée"
                } else {
                    "Récupérable"
                },
                item.job_id,
                item.generation.get(),
                item.source_sha256
            ));
            if let Some(diagnostic) = &item.diagnostic {
                ui.colored_label(egui::Color32::LIGHT_RED, diagnostic);
            }
        }
    }
}

fn parse_sha256(value: &str) -> [u8; 32] {
    let mut bytes = [0_u8; 32];
    for (index, pair) in value.as_bytes().as_chunks::<2>().0.iter().enumerate() {
        bytes[index] = (hex_digit(pair[0]) << 4) | hex_digit(pair[1]);
    }
    bytes
}
fn hex_digit(value: u8) -> u8 {
    match value {
        b'0'..=b'9' => value - b'0',
        b'a'..=b'f' => value - b'a' + 10,
        _ => 0,
    }
}

use std::{fs::File, path::Path};
use symphonia::core::{
    audio::{AudioBufferRef, SampleBuffer},
    codecs::DecoderOptions,
    errors::Error,
    formats::FormatOptions,
    io::MediaSourceStream,
    meta::MetadataOptions,
    probe::Hint,
};
use whisper_core::ports::DecodeRequest;

pub const OUTPUT_RATE: u32 = 16_000;
pub const MAX_WINDOW_SAMPLES: usize = 80_000;

pub fn decode_requested_block(request: &DecodeRequest) -> Result<Option<Vec<i16>>, String> {
    let requested_range = request
        .range
        .end_sample
        .saturating_sub(request.range.start_sample);
    if request.max_samples == 0
        || request.max_samples > MAX_WINDOW_SAMPLES
        || request.range.sample_rate_hz != OUTPUT_RATE
        || request.range.start_sample >= request.range.end_sample
    {
        return Err("InvalidRequest: decode range exceeds the 80,000-sample bound".into());
    }
    let requested = requested_range.min(request.max_samples as u64);
    let requested_end = request.range.start_sample + requested;
    let capacity = usize::try_from(requested).map_err(|_| "InvalidRequest: range too large")?;
    let mut samples = Vec::with_capacity(capacity);
    let (_, total_samples) =
        decode_wav_windows(Path::new(&request.source.source_id), |start, window| {
            let window_end = start + window.len() as u64;
            let from = request.range.start_sample.max(start);
            let to = requested_end.min(window_end);
            if from < to {
                samples.extend(
                    window[(from - start) as usize..(to - start) as usize]
                        .iter()
                        .map(|sample| (sample.clamp(-1.0, 1.0) * i16::MAX as f32).round() as i16),
                );
            }
            Ok(())
        })?;
    if request.range.start_sample >= total_samples {
        return Ok(None);
    }
    let actual_samples = requested_end.min(total_samples) - request.range.start_sample;
    if samples.len() as u64 != actual_samples {
        return Err(
            "DecodeFailed: decoded block length differs from the bounded source range".into(),
        );
    }
    Ok(Some(samples))
}

pub fn decode_wav_windows(
    path: &Path,
    mut on_window: impl FnMut(u64, Vec<f32>) -> Result<(), String>,
) -> Result<(u64, u64), String> {
    let file = File::open(path).map_err(|e| format!("source open failed: {e}"))?;
    let mss = MediaSourceStream::new(Box::new(file), Default::default());
    let mut hint = Hint::new();
    hint.with_extension("wav");
    let probed = symphonia::default::get_probe()
        .format(
            &hint,
            mss,
            &FormatOptions::default(),
            &MetadataOptions::default(),
        )
        .map_err(|e| format!("UnsupportedFormat: WAV probe failed: {e}"))?;
    let mut format = probed.format;
    let track = format
        .default_track()
        .ok_or_else(|| "WAV has no default audio track".to_owned())?;
    let track_id = track.id;
    let sample_rate = track
        .codec_params
        .sample_rate
        .ok_or_else(|| "WAV sample rate missing".to_owned())?;
    let channels = track
        .codec_params
        .channels
        .ok_or_else(|| "WAV channel count missing".to_owned())?
        .count();
    if sample_rate == 0 || channels == 0 || channels > 32 {
        return Err("UnsupportedFormat: unsupported WAV audio layout".into());
    }
    #[cfg(feature = "l01-memory-qualification")]
    crate::memory_qualification::record(
        "codec.ready",
        serde_json::json!({
            "sample_rate_hz": sample_rate,
            "channels": channels,
            "wav_pcm_max_frames_per_packet": 1_152,
            "window_max_samples": MAX_WINDOW_SAMPLES,
        }),
    );
    let mut decoder = symphonia::default::get_codecs()
        .make(&track.codec_params, &DecoderOptions::default())
        .map_err(|e| format!("WAV decoder init failed: {e}"))?;
    let mut window = Vec::with_capacity(MAX_WINDOW_SAMPLES);
    let mut decoded_frames = 0_u64;
    let mut output_samples = 0_u64;
    let mut previous = None::<f32>;
    let mut next_output = 0_u64;
    let mut input_index = 0_u64;
    #[cfg(feature = "l01-memory-qualification")]
    let mut packet_index = 0_u64;
    #[cfg(feature = "l01-memory-qualification")]
    let mut window_index = 0_u64;
    loop {
        let packet = match format.next_packet() {
            Ok(p) => p,
            Err(Error::IoError(e)) if e.kind() == std::io::ErrorKind::UnexpectedEof => break,
            Err(e) => return Err(format!("WAV packet read failed: {e}")),
        };
        #[cfg(feature = "l01-memory-qualification")]
        {
            packet_index += 1;
        }
        #[cfg(feature = "l01-memory-qualification")]
        crate::memory_qualification::record(
            "codec.packet.read",
            serde_json::json!({
                "packet_index": packet_index,
                "packet_payload_bytes": packet.data.len(),
                "packet_duration_timebase_units": packet.dur,
            }),
        );
        if packet.track_id() != track_id {
            continue;
        }
        let decoded = decoder
            .decode(&packet)
            .map_err(|e| format!("WAV decode failed: {e}"))?;
        #[cfg(feature = "l01-memory-qualification")]
        let decoded_frame_capacity = decoded.capacity();
        #[cfg(feature = "l01-memory-qualification")]
        let decoded_frame_count = decoded.frames();
        let mut samples = SampleBuffer::<f32>::new(decoded.capacity() as u64, *decoded.spec());
        samples.copy_interleaved_ref(decoded);
        let interleaved = samples.samples();
        #[cfg(feature = "l01-memory-qualification")]
        crate::memory_qualification::record(
            "codec.sample_buffer.live",
            serde_json::json!({
                "packet_index": packet_index,
                "packet_payload_bytes": packet.data.len(),
                "decoded_frame_capacity": decoded_frame_capacity,
                "decoded_frames": decoded_frame_count,
                "sample_buffer_initialized_samples": samples.len(),
                "sample_buffer_capacity_samples": samples.capacity(),
                "sample_buffer_capacity_bytes": samples.capacity() * std::mem::size_of::<f32>(),
                "channel_count": channels,
            }),
        );
        let count = interleaved.len() / channels;
        for frame in 0..count {
            let current = interleaved[frame * channels..(frame + 1) * channels]
                .iter()
                .copied()
                .sum::<f32>()
                / channels as f32;
            if let Some(prev) = previous {
                while next_output.saturating_mul(u64::from(sample_rate))
                    <= input_index.saturating_mul(u64::from(OUTPUT_RATE))
                {
                    let numerator = next_output.saturating_mul(u64::from(sample_rate));
                    let base = numerator / u64::from(OUTPUT_RATE);
                    let frac = (numerator % u64::from(OUTPUT_RATE)) as f32 / OUTPUT_RATE as f32;
                    let value = if base == input_index {
                        current
                    } else {
                        prev + (current - prev) * frac
                    };
                    window.push(value.clamp(-1.0, 1.0));
                    output_samples += 1;
                    next_output += 1;
                    if window.len() == MAX_WINDOW_SAMPLES {
                        let start = output_samples - window.len() as u64;
                        let full_window =
                            std::mem::replace(&mut window, Vec::with_capacity(MAX_WINDOW_SAMPLES));
                        #[cfg(feature = "l01-memory-qualification")]
                        {
                            window_index += 1;
                        }
                        #[cfg(feature = "l01-memory-qualification")]
                        crate::memory_qualification::record(
                            "pcm.window.callback.begin",
                            serde_json::json!({
                                "window_index": window_index,
                                "source_start_sample": start,
                                "source_sample_count_total": output_samples,
                                "outgoing_window_len": full_window.len(),
                                "outgoing_window_capacity": full_window.capacity(),
                                "replacement_window_len": window.len(),
                                "replacement_window_capacity": window.capacity(),
                                "simultaneous_pcm_window_capacity_bytes": (full_window.capacity() + window.capacity()) * std::mem::size_of::<f32>(),
                                "codec_packet_payload_bytes_still_live": packet.data.len(),
                                "codec_sample_buffer_capacity_bytes_still_live": samples.capacity() * std::mem::size_of::<f32>(),
                            }),
                        );
                        on_window(start, full_window)?;
                        #[cfg(feature = "l01-memory-qualification")]
                        crate::memory_qualification::record(
                            "pcm.window.callback.complete",
                            serde_json::json!({
                                "window_index": window_index,
                                "replacement_window_len": window.len(),
                                "replacement_window_capacity": window.capacity(),
                            }),
                        );
                    }
                }
            } else {
                window.push(current.clamp(-1.0, 1.0));
                output_samples = 1;
                next_output = 1;
            }
            previous = Some(current);
            input_index += 1;
            decoded_frames += 1;
        }
    }
    if !window.is_empty() {
        let start = output_samples - window.len() as u64;
        #[cfg(feature = "l01-memory-qualification")]
        {
            window_index += 1;
        }
        #[cfg(feature = "l01-memory-qualification")]
        let tail_samples = window.len();
        #[cfg(feature = "l01-memory-qualification")]
        let tail_capacity = window.capacity();
        #[cfg(feature = "l01-memory-qualification")]
        crate::memory_qualification::record(
            "pcm.window.callback.begin",
            serde_json::json!({
                "window_index": window_index,
                "source_start_sample": start,
                "source_sample_count_total": output_samples,
                "outgoing_window_len": window.len(),
                "outgoing_window_capacity": window.capacity(),
                "replacement_window_capacity": 0,
                "simultaneous_pcm_window_capacity_bytes": window.capacity() * std::mem::size_of::<f32>(),
            }),
        );
        on_window(start, window)?;
        #[cfg(feature = "l01-memory-qualification")]
        crate::memory_qualification::record(
            "pcm.window.callback.complete",
            serde_json::json!({
                "window_index": window_index,
                "released_window_samples": tail_samples,
                "released_window_capacity": tail_capacity,
                "replacement_window_capacity": 0,
            }),
        );
    }
    #[cfg(feature = "l01-memory-qualification")]
    crate::memory_qualification::record(
        "codec.complete",
        serde_json::json!({
            "packet_count": packet_index,
            "window_count": window_index,
            "decoded_frames": decoded_frames,
            "output_samples": output_samples,
            "retained_full_source_pcm_samples": 0,
        }),
    );
    Ok((decoded_frames, output_samples))
}

